async function updateList(){const mv=document.querySelector('[data-more-view]');if(mv)mv.value=MORE_VIEWS.includes(view)?view:'';const form=document.querySelector('#filters');const params=new URLSearchParams({view});for(const [k,v]of new FormData(form))if(v)params.set(k,v);const [items,apps]=await Promise.all([api('/api/opportunities?'+params),appsCache?Promise.resolve(appsCache):api('/api/application-list').catch(()=>[])]);appsCache=apps;history.replaceState(null,'','/opportunities?'+params);document.querySelector('#opportunity-list').innerHTML=rows(items,Object.fromEntries(apps.map(x=>[x.opportunity_id,x])));}
document.addEventListener('change',async e=>{const s=e.target.closest('[data-more-view]');if(!s||!s.value)return;view=s.value;document.querySelectorAll('[data-view]').forEach(x=>x.classList.remove('active'));try{await updateList();}catch(err){toast(err.message,true);}});
function materialList(label,items){return `<h3>${E(label)}</h3>${items.length?`<ul>${items.map(m=>`<li>${E(m.label)}${m.reason?`<br><small>${E(m.reason)}</small>`:''}</li>`).join('')}</ul>`:'<p class="small">None confirmed.</p>'}`;}
function creditConditions(d){
 const b=d.data.credit_benefits||{};if(!b.provider&&d.data.funding.credits_value===null)return '';
 const labels={provider:'Provider',tier:'Award tier',category:'Usage category',referral_required:'Referral required',company_email_required:'Company email required',paid_account_required:'Paid account required',deposit_required:'Deposit required',minimum_spend:'Minimum spend',expiration_months:'Expires after (months)',eligible_products:'Eligible products',excluded_products:'Excluded products',renewal_behavior:'After credits expire',stacking_restrictions:'Stacking restrictions',terms_acceptance_required:'Terms acceptance required'};
 const known=Object.entries(labels).filter(([k])=>b[k]!==null&&b[k]!==undefined),unknown=Object.keys(labels).length-known.length;
 return '<details class="more"><summary>Credits &amp; conditions</summary><p class="small">'+E(d.analysis.credits?.cost_status||'Payment conditions need review')+'</p>'+(known.length?'<dl>'+known.map(([k,l])=>'<dt>'+E(l)+'</dt><dd>'+E(typeof b[k]==='boolean'?(b[k]?'Yes':'No'):b[k])+'</dd>').join('')+'</dl>':'')+(unknown?'<p class="small">'+plural(unknown,'condition')+' not published yet.</p>':'')+'<p class="small">'+E(d.analysis.credits?.value_note||'Credits are restricted benefits, not cash.')+'</p></details>';
}
